const tasks = $('Postgres: Completed Tasks').first().all();
const chatMetrics = $('Postgres: Chat Metrics').first().all();
const usageMetrics = $('Postgres: Usage Metrics').first().all();
const totalTasks = tasks.length;
const completedTasks = tasks.filter(t => t.json.status === 'completed').length;
const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
const activeConversations = chatMetrics.length > 0 ? parseInt(chatMetrics[0].json.count) : 0;
const apiCalls = usageMetrics.filter(m => m.json.metric_name === 'api_call').reduce((sum, m) => sum + parseInt(m.json.metric_value || 0), 0);
const storageGb = usageMetrics.filter(m => m.json.metric_name === 'storage_gb').reduce((sum, m) => sum + parseFloat(m.json.metric_value || 0), 0);
const topClients = tasks.reduce((acc, t) => {
  const cid = t.json.client_id || 'unknown';
  acc[cid] = (acc[cid] || 0) + 1;
  return acc;
}, {});
const topClientsArr = Object.entries(topClients).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([cid, count]) => ({ client_id: cid, task_count: count }));
const alerts = [];
if (completionRate < 50) alerts.push('Low completion rate: ' + completionRate + '%');
if (activeConversations === 0) alerts.push('No active conversations in 24h');
if (apiCalls > 10000) alerts.push('High API usage: ' + apiCalls + ' calls');
const report = {
  total_tasks: totalTasks,
  completion_rate: completionRate,
  active_conversations: activeConversations,
  api_calls: apiCalls,
  storage_gb: storageGb,
  top_clients: topClientsArr,
  alerts: alerts,
  generated_at: new Date().toISOString()
};
return [{ json: report }];
